import numpy as np
import os, sys
sys.path.append("storage/verity")
try:
    import scp_lp_core as core
except Exception:
    core = None

N = 32
R_MIN = 1e-8

def _solve_exact(C):
    r, _ = core.solve_radii_lp_zero_slack(C)
    r = core.finalize_zero_tol_iter(C, r)
    return r, float(np.sum(r))

def _slacks(C, r):
    n = C.shape[0]
    pairs = []
    for i in range(n):
        for j in range(i+1, n):
            d = float(np.linalg.norm(C[i] - C[j]))
            s = d - (r[i] + r[j])
            pairs.append((s, i, j, d))
    pairs.sort(key=lambda t: t[0])
    return pairs  # ascending by slack

def _in_box(C, margin=0.0):
    return np.all(C[:,0] >= 0.0+margin) and np.all(C[:,0] <= 1.0-margin) and \
           np.all(C[:,1] >= 0.0+margin) and np.all(C[:,1] <= 1.0-margin)

def _rotate_pair(C, i, j, theta):
    # Rotate i and j around their midpoint m by angle theta
    ci = C[i].copy(); cj = C[j].copy()
    m = 0.5 * (ci + cj)
    vi = ci - m; vj = cj - m  # vj = -vi ideally
    ct = np.cos(theta); st = np.sin(theta)
    Ri = np.array([[ct, -st],[st, ct]])
    vi_new = Ri @ vi
    vj_new = -vi_new
    Ci = m + vi_new
    Cj = m + vj_new
    C_new = C.copy()
    C_new[i] = Ci
    C_new[j] = Cj
    return C_new

def _try_pivot(C, i, j, angles):
    best = (-1.0, None, None)
    for th in angles:
        # both signs
        for sgn in (+1.0, -1.0):
            theta = sgn * th
            C_try = _rotate_pair(C, i, j, theta)
            if not _in_box(C_try, margin=0.0):
                continue
            r_try, score = _solve_exact(C_try)
            if score > best[0]:
                best = (score, C_try, r_try)
    return best[1], best[2], best[0]

def _seed_storage_best():
    try:
        C = np.load("storage/verity/best_centers.npy")
        if isinstance(C, np.ndarray) and C.shape == (N,2):
            return np.clip(C.astype(float), 0.0, 1.0)
    except Exception:
        pass
    return None

def _seed_grid_minus_corners():
    xs = np.linspace(0.1, 0.9, 6)
    ys = np.linspace(0.1, 0.9, 6)
    centers = []
    for ix, x in enumerate(xs):
        for iy, y in enumerate(ys):
            if (ix in (0,5)) and (iy in (0,5)):
                continue
            centers.append([x, y])
    return np.array(centers, dtype=float)

def construct_packing() -> tuple:
    if core is None:
        # Fallback trivial
        C = _seed_grid_minus_corners()
        r = np.full((N,), 0.02, dtype=float)
        return C, r

    C0 = _seed_storage_best()
    if C0 is None:
        C0 = _seed_grid_minus_corners()

    # Baseline exact solve
    r0, s0 = _solve_exact(C0)
    best_C, best_r, best_s = C0.copy(), r0.copy(), s0
    print(f"[dcpp] start sum={best_s:.17f}")

    # Iterative DCPP passes over low‑slack pairs
    max_pass = 10
    top_M = 10
    angles = [0.004, 0.002, 0.001, 0.0005, 0.00025]

    for it in range(max_pass):
        pairs = _slacks(best_C, best_r)
        improved = False
        # focus on most binding pairs
        for k in range(min(top_M, len(pairs))):
            s, i, j, d = pairs[k]
            C_try, r_try, s_try = _try_pivot(best_C, i, j, angles)
            if C_try is None:
                continue
            if s_try > best_s + 1e-9:
                print(f"[dcpp] it={it} pair=({i},{j}) slack={s:.3e} -> sum={s_try:.17f}")
                best_C, best_r, best_s = C_try, r_try, s_try
                improved = True
                break  # restart pair scan from new state
        if not improved:
            break

    # Persist best
    try:
        os.makedirs("storage/verity", exist_ok=True)
        np.save("storage/verity/best_centers.npy", best_C)
        np.save("storage/verity/best_radii.npy", best_r)
    except Exception:
        pass

    return np.array(best_C, dtype=float), np.array(best_r, dtype=float)
